    27
    >>> count_k_palindromic_numbers(1, 4)
    2
    >>> count_k_palindromic_numbers(5, 6)
    2468
    """

    count = 0
    if n == 1:
        for i in range(1, 10):
            if i % k == 0:
                count += 1
        return count

    if n == 2:
        for i in range(1, 10):
